answer:
def average(scores):
    if len(scores) == 0:
        return 0
    return sum(scores) / len(scores)

print(average([80, 90, 70]))

starter:
def fizzbuzz(n):
    return str(n)

for i in range(1, 16):
    print(fizzbuzz(i))

answer:
def fizzbuzz(n):
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

for i in range(1, 16):
    print(fizzbuzz(i))
